+/// file. The module's root needs no mark.
+pub fn source_path_to_posix(path: &Path) -> String {
+    let mut posix = relative_path_to_posix(path);
+    if !posix.is_empty() && posix != "." && typed_as_directory(path) {
+        posix.push('/');
+    }
+    posix
+}
