89:/// Resolve and classify explicit purge targets without following symlinks.
90:/// Containment is verified before even reading target metadata, then verified
91:/// again by [`execute_deletion_plan`] immediately before mutation.
92:pub fn classify_explicit_targets(
93:    module_root: &Path,
94:    canonical_root: &Path,
95:    rel_paths: impl IntoIterator<Item = PathBuf>,
96:    operation: &'static str,
97:) -> Result<(Vec<PathBuf>, Vec<PathBuf>), DeletionError> {
98:    let mut files = Vec::new();
99:    let mut dirs = Vec::new();
100:    for rel in rel_paths {
101:        if rel.as_os_str().is_empty() || rel == Path::new(".") {
102:            continue;
103:        }
104:        let target = module_root.join(rel);
105:        crate::path_safety::verify_contained(canonical_root, &target).map_err(|source| {
106:            DeletionError::Containment {
107:                operation,
108:                target: target.clone(),
109:                source,
110:            }
111:        })?;
112:        let metadata = match std::fs::symlink_metadata(&target) {
113:            Ok(metadata) => metadata,
114:            Err(error) if error.kind() == std::io::ErrorKind::NotFound => continue,
115:            Err(source) => {
116:                return Err(DeletionError::Filesystem {
117:                    operation,
118:                    action: "stat",
119:                    target,
120:                    source,
121:                });
122:            }
123:        };
124:        if metadata.file_type().is_dir() {
125:            dirs.push(target);
126:        } else {
127:            files.push(target);
128:        }
129:    }
130:    Ok((files, dirs))
131:}
