83:impl Unit for char {
84:    fn ascii(self) -> Option<u8> {
85:        self.is_ascii().then_some(self as u8)
86:    }
87:    /// The character's simple lowercase mapping — one character for one.
88:    /// The standard library gives the full mapping, which differs for a
89:    /// single character: `İ` (U+0130) becomes `i` and a combining dot,
90:    /// where the simple mapping, and the reference, give `i`.
91:    fn lower(self) -> Self {
92:        if self == '\u{130}' {
93:            return 'i';
94:        }
95:        self.to_lowercase().next().unwrap_or(self)
96:    }
97:    /// The classes of the reference's locale, `C.UTF-8`, by that
98:    /// locale's own tables (cr-uv2-6): [`reference_classes`], read from
99:    /// the C library for every code point, the ones no character is
100:    /// assigned to among them. They are not the standard library's
101:    /// predicates of the same names — there a no-break space is a
102:    /// `space`, an em space no `blank`, a digit of another script no
103:    /// `alpha`, a title-case letter not `upper` — and they are not
104:    /// written over this build's Unicode data, as cr-uv1-7 had them:
105:    /// the standard library cannot say that a code point is unassigned,
106:    /// so U+0378 was printable here and is not to `find`, and a compiler
107:    /// with newer tables than the reference's would have moved the
108:    /// classes with it.
109:    ///
110:    /// Four classes are tables. The other eight are those and a few
111:    /// fixed code points, by identities that hold for every code point
112:    /// of the reference (guarded on Linux against the library itself).
113:    fn is(self, class: Class) -> bool {
114:        use reference_classes::{ALPHA, LOWER, PRINT, UPPER};
115:        let point = self as u32;
116:        match class {
117:            Class::Alpha => within(&ALPHA, point),
118:            Class::Digit => self.is_ascii_digit(),
119:            Class::Alnum => self.is(Class::Alpha) || self.is_ascii_digit(),
120:            Class::Upper => within(&UPPER, point),
121:            Class::Lower => within(&LOWER, point),
122:            // No no-break space among them, and not the C1 "next line".
123:            Class::Space => matches!(
124:                point,
125:                0x9..=0xd
126:                    | 0x20
127:                    | 0x1680
128:                    | 0x2000..=0x2006
129:                    | 0x2008..=0x200a
130:                    | 0x2028
131:                    | 0x2029
132:                    | 0x205f
133:                    | 0x3000
134:            ),
135:            // A space that is no control, and the tab.
136:            Class::Blank => self == '\t' || (self.is(Class::Space) && !self.is(Class::Cntrl)),
137:            // The two separators count as controls.
138:            Class::Cntrl => matches!(point, 0..=0x1f | 0x7f..=0x9f | 0x2028 | 0x2029),
139:            Class::Xdigit => self.is_ascii_hexdigit(),
140:            Class::Print => within(&PRINT, point),
141:            Class::Graph => self.is(Class::Print) && !self.is(Class::Space),
142:            // Every graphic character that is no letter and no digit.
143:            Class::Punct => {
144:                self.is(Class::Graph) && !self.is(Class::Alpha) && !self.is_ascii_digit()
145:            }
146:        }
147:    }
148:}
