226:fn compile<U: Unit>(pattern: &[U]) -> Result<Vec<Token<U>>, String> {
227:    let mut tokens = Vec::new();
228:    let mut at = 0;
229:    while let Some(&unit) = pattern.get(at) {
230:        at += 1;
231:        let token = if is(unit, b'*') {
232:            // A run of stars is one.
233:            if tokens.last() == Some(&Token::Run) {
234:                continue;
235:            }
236:            Token::Run
237:        } else if is(unit, b'?') {
238:            Token::One
239:        } else if is(unit, b'\\') {
240:            match pattern.get(at) {
241:                Some(&escaped) => {
242:                    at += 1;
243:                    Token::Literal(escaped)
244:                }
245:                None => Token::Nothing,
246:            }
247:        } else if is(unit, b'[') {
248:            match set(pattern, at)? {
249:                Some((token, after)) => {
250:                    at = after;
251:                    token
252:                }
253:                // Never closed: a `[` like any other character.
254:                None => Token::Literal(unit),
255:            }
256:        } else {
257:            Token::Literal(unit)
258:        };
259:        tokens.push(token);
260:    }
261:    Ok(tokens)
262:}
