369:fn fits<U: Unit>(tokens: &[Token<U>], name: &[U], ignore_case: bool) -> bool {
370:    let (mut token, mut unit) = (0, 0);
371:    // Where to go back to: the token after the last `*`, and how much of
372:    // the name that star has taken so far.
373:    let mut star: Option<(usize, usize)> = None;
374:    loop {
375:        match tokens.get(token) {
376:            Some(Token::Run) => {
377:                star = Some((token + 1, unit));
378:                token += 1;
379:                continue;
380:            }
381:            Some(Token::Nothing) => return false,
382:            Some(one) if unit < name.len() && one.takes(name[unit], ignore_case) => {
383:                token += 1;
384:                unit += 1;
385:                continue;
386:            }
387:            None if unit == name.len() => return true,
388:            _ => {}
389:        }
390:        match star {
391:            Some((after, taken)) if taken < name.len() => {
392:                star = Some((after, taken + 1));
393:                token = after;
394:                unit = taken + 1;
395:            }
396:            _ => return false,
397:        }
398:    }
399:}
