91:/// Whether a path is written so that it names a directory and nothing
92:/// else: with a separator after it, or with `.` as its last name. The
93:/// system resolves a link standing there and refuses anything that is no
94:/// directory (`Not a directory`). [`Path::components`] drops both marks.
95:pub fn typed_as_directory(path: &Path) -> bool {
96:    let typed = path.as_os_str().as_encoded_bytes();
97:    let is_separator = |byte: &u8| *byte == b'/' || (cfg!(windows) && *byte == b'\\');
98:    match typed.last() {
99:        None => false,
100:        Some(last) if is_separator(last) => true,
101:        Some(_) => typed.rsplit(is_separator).next() == Some(b".".as_slice()),
102:    }
103:}
