78:pub(crate) fn resolve_relative_path(rel: &str) -> Result<PathBuf, Status> {
79:    // Request-path-context fold: directory references (".", "./", "")
80:    // all map to "module root." Done before strict file-path validation
81:    // so the strict validator can keep rejecting these forms in
82:    // file-path contexts.
83:    let trimmed = rel.trim_end_matches('/');
84:    if trimmed.is_empty() || trimmed == "." {
85:        return Ok(PathBuf::from("."));
86:    }
87:    let normalized = blit_core::path_safety::validate_wire_path(rel)
88:        .map_err(|e| Status::invalid_argument(format!("path not allowed: {}: {e}", rel)))?;
89:    if normalized.as_os_str().is_empty() {
90:        Ok(PathBuf::from("."))
91:    } else {
92:        Ok(normalized)
93:    }
94:}
