120:pub(crate) fn resolve_contained_path(module: &ModuleConfig, rel: &Path) -> Result<PathBuf, Status> {
121:    let target = resolve_dest_path(&module.path, rel);
122:    blit_core::path_safety::verify_contained(&module.canonical_root, &target)
123:        .map_err(|e| Status::permission_denied(format!("path containment: {e:#}")))?;
124:    Ok(target)
125:}
