185:fn remove_each(
186:    module_path: &Path,
187:    canonical_root: &Path,
188:    operands: &[RmOperand],
189:    options: blit_core::deletion::RmOptions,
190:    called_off: &dyn Fn() -> bool,
191:    failed: &mut dyn FnMut(RmFailure) -> Result<(), Stopped>,
192:) -> Result<u64, Status> {
193:    let closed = || response_channel_closed("sending removal result");
194:    let mut entries_removed = 0u64;
195:    for (operand, rel) in operands.iter().enumerate() {
196:        let rel = match rel {
197:            Ok(rel) => rel,
198:            Err(reason) => {
199:                failed(RmFailure {
200:                    operand: operand as u32,
201:                    relative_path: String::new(),
202:                    raw_relative_path: None,
203:                    reason: reason.clone(),
204:                })
205:                .map_err(|Stopped| closed())?;
206:                continue;
207:            }
208:        };
209:        let removed = blit_core::deletion::remove_as_rm_reporting(
210:            &module_path.join(&rel.rel),
211:            rel.as_directory,
212:            Some(canonical_root),
213:            options,
214:            Some(called_off),
215:            &mut |failure| {
216:                failed(RmFailure {
217:                    operand: operand as u32,
218:                    relative_path: wire_path(&failure.relative_path),
219:                    raw_relative_path: blit_core::raw_name::raw_relative_bytes(
220:                        &failure.relative_path,
221:                    ),
222:                    reason: os_reason(&failure.error),
223:                })
