786:fn looks_like_windows_absolute(s: &str) -> bool {
787:    // UNC and NT/DOS device paths.
788:    if s.starts_with("\\\\") || s.starts_with("//") {
789:        return true;
790:    }
791:    // Single leading backslash. On Unix this is a normal char as far as
792:    // Path::components is concerned, but in the protocol context this
793:    // is a Windows-shaped root path (e.g. `\Windows\System32`) and
794:    // should be rejected uniformly across hosts.
795:    if s.starts_with('\\') {
796:        return true;
797:    }
798:    // Drive-letter forms: at least 2 chars where chars[0] is ASCII alpha
799:    // and chars[1] is ':'.
800:    let bytes = s.as_bytes();
801:    bytes.len() >= 2 && bytes[1] == b':' && bytes[0].is_ascii_alphabetic()
802:}
