19:pub async fn run_du(args: DuArgs) -> Result<ExitCode> {
20:    // The operand as typed (cr-uv1-1, cr-uv1-4): `du link/` is the
21:    // directory the link points to, said by the separator; and a path
22:    // need not be text.
23:    let Some(operand) = Operand::read(&args.target)? else {
24:        bail!(
25:            "`blit du` requires a remote path (received local path: {})",
26:            args.target.to_string_lossy()
27:        );
28:    };
29:    let options = usage_options(&args)?;
30:    let (remote, module, start_path) = (
31:        operand.remote.clone(),
32:        operand.module.clone(),
33:        operand.wire_path(),
34:    );
35:    let size = |bytes: u64| {
36:        if args.human_readable {
37:            human_size(bytes)
38:        } else {
39:            blocks_1k(bytes).to_string()
40:        }
41:    };
42:
43:    let mut failed = false;
44:    if args.json {
45:        let mut rows = Vec::new();
46:        let mut failures = Vec::new();
47:        du::stream(&remote, module, start_path, options, |event| {
48:            match event {
49:                DuEvent::Row {
50:                    path,
51:                    allocated_bytes,
52:                } => rows.push(serde_json::json!({
53:                    "path": String::from_utf8_lossy(&operand.below(&path)),
54:                    "allocated_bytes": allocated_bytes,
55:                })),
56:                DuEvent::Failure {
57:                    path,
58:                    action,
59:                    reason,
60:                } => failures.push(serde_json::json!({
61:                    "path": String::from_utf8_lossy(&operand.below(&path)),
62:                    "action": action,
63:                    "reason": reason,
64:                })),
65:            }
66:            Ok(())
67:        })
68:        .await?;
69:        failed = !failures.is_empty();
70:        println!(
71:            "{}",
72:            serde_json::to_string_pretty(
73:                &serde_json::json!({ "rows": rows, "failures": failures })
74:            )?
75:        );
76:    } else {
77:        du::stream(&remote, module, start_path, options, |event| {
78:            match event {
79:                DuEvent::Row {
80:                    path,
81:                    allocated_bytes,
82:                } => {
83:                    // The path's own bytes: a name that is not valid text
84:                    // is printed as the name it is.
85:                    let mut line = size(allocated_bytes).into_bytes();
86:                    line.push(b'\t');
87:                    line.extend_from_slice(&operand.below(&path));
88:                    line.push(b'\n');
89:                    std::io::stdout().lock().write_all(&line)?;
90:                }
91:                DuEvent::Failure {
92:                    path,
93:                    action,
94:                    reason,
95:                } => {
96:                    failed = true;
97:                    // The name as `du` writes it (cr-uv2-5).
98:                    eprintln!(
99:                        "blit du: {action} {}: {reason}",
100:                        blit_core::admin::quote::for_shell(&operand.below(&path), true)
101:                    );
102:                }
103:            }
104:            Ok(())
105:        })
106:        .await?;
107:    }
108:
109:    Ok(if failed {
110:        ExitCode::from(1)
111:    } else {
112:        ExitCode::SUCCESS
113:    })
114:}
