42:fn parse(words: &[OsString]) -> Result<Expression> {
43:    let mut expression = Expression::default();
44:    let mut words = words.iter();
45:    while let Some(word) = words.next() {
46:        // A test's own name is text; its argument need not be (cr-uv1-4:
47:        // a name `find` prints by its bytes can be a `-name` pattern).
48:        let word = word.to_string_lossy();
49:        let word = word.as_ref();
50:        let mut argument = |what: &str| -> Result<&OsString> {
51:            match words.next() {
52:                Some(argument) => Ok(argument),
53:                None => bail!("missing argument to `{word}': {what}"),
54:            }
55:        };
56:        match word {
57:            "-name" | "-iname" => {
58:                let typed = argument("a pattern")?;
59:                let pattern = operand::word_bytes(typed)?;
60:                let ignore_case = word == "-iname";
61:                // Read here as the daemon will read it: a pattern it would
62:                // refuse is refused before anything is asked.
63:                NamePattern::new(pattern, ignore_case).map_err(|refusal| {
64:                    eyre::eyre!("{word} '{}': {refusal}", typed.to_string_lossy())
65:                })?;
66:                expression.names.push(NameTest {
67:                    pattern: pattern.to_vec(),
68:                    ignore_case,
69:                });
70:            }
71:            "-type" => {
72:                let kind = argument("f, d or l")?.to_string_lossy();
73:                expression.kinds.push(match kind.as_ref() {
74:                    "f" => Kind::File,
75:                    "d" => Kind::Directory,
76:                    "l" => Kind::Link,
77:                    other => bail!("-type {other} is not supported: -type takes f, d or l"),
78:                })
79:            }
80:            "-maxdepth" => {
81:                let depth = argument("a number of levels")?.to_string_lossy();
82:                expression.max_depth = Some(depth.parse().map_err(|_| {
83:                    eyre::eyre!("-maxdepth {depth}: expected a number of levels, 0 or more")
84:                })?);
