42:pub async fn run_rm(args: RmArgs) -> Result<ExitCode> {
43:    // Every operand is read before anything is asked or sent: one that
44:    // cannot be an operand at all refuses the command whole. Each is kept
45:    // as typed (cr-uv1-1) and by its bytes (cr-uv1-4): a separator after
46:    // it, a `.`, a space at its end, a name that is not text.
47:    let mut operands = Vec::with_capacity(args.targets.len());
48:    for typed in &args.targets {
49:        let Some(read) = Operand::read(typed)? else {
50:            bail!(
51:                "`blit rm` only supports remote paths (received local path: {})",
52:                typed.to_string_lossy()
53:            );
54:        };
55:        if operand::is_the_root(read.path()) {
56:            bail!(
57:                "refusing to delete entire module '{}'; specify a sub-path",
58:                read.module
59:            );
60:        }
61:        operands.push(read);
62:    }
63:
64:    // `rm` refuses a path whose last name is `.` or `..` whatever its
65:    // options, and goes on to the others (cr-uv1-1: `work/.` was sent as
66:    // `work`, and `work` removed). Such an operand is neither asked about
67:    // nor sent.
68:    let mut refused: Vec<Failed> = Vec::new();
69:    let mut asked: Vec<usize> = Vec::new();
70:    for (at, each) in operands.iter().enumerate() {
71:        if operand::names_dot(each.path()) {
72:            refused.push(Failed {
73:                operand: at,
74:                path: each.typed().to_vec(),
75:                reason: DOT_OR_DOT_DOT.to_string(),
76:                refused: true,
77:            });
78:        } else {
79:            asked.push(at);
80:        }
81:    }
82:
83:    // The question, once, for the whole command (Q1, D-2026-11-20-3).
84:    if !asked.is_empty()
85:        && !crate::confirm::confirm(
86:            None,
87:            &question(asked.iter().map(|&at| &operands[at])),
88:            args.yes || args.force,
89:            "-y (or -f)",
90:        )?
91:    {
92:        println!("Aborted.");
93:        return Ok(ExitCode::SUCCESS);
94:    }
95:
96:    // One request per daemon and module, in the order first named.
97:    let mut groups: Vec<Vec<usize>> = Vec::new();
98:    for &at in &asked {
99:        let operand = &operands[at];
100:        let same = |other: &Operand| {
101:            other.remote.host == operand.remote.host
102:                && other.remote.port == operand.remote.port
103:                && other.module == operand.module
104:        };
105:        match groups.iter_mut().find(|group| same(&operands[group[0]])) {
106:            Some(group) => group.push(at),
107:            None => groups.push(vec![at]),
108:        }
109:    }
110:
111:    let options = RmOptions {
112:        recursive: args.recursive,
113:        force: args.force,
114:    };
115:    // What is said, as it is learned (cr-uv1-5): each entry the daemon
116:    // could not remove is printed when the daemon reports it, every one of
117:    // them, in the order the operands were typed.
118:    let mut said = Said {
119:        json: args.json,
120:        listed: Vec::new(),
121:        refused: refused.into(),
122:        any: false,
123:    };
124:    let mut entries_removed = 0u64;
125:    let mut unfinished: Vec<String> = Vec::new();
126:    for group in groups {
127:        let first = &operands[group[0]];
128:        let paths = group.iter().map(|&at| operands[at].wire_path()).collect();
129:        let answered = rm::remove(
130:            &first.remote,
131:            first.module.clone(),
132:            paths,
133:            options,
134:            |failure| {
135:                let Some(&at) = group.get(failure.operand) else {
136:                    return;
137:                };
138:                said.failed(Failed {
139:                    operand: at,
140:                    path: operands[at].below(&failure.path),
141:                    reason: failure.reason,
142:                    refused: false,
143:                });
144:            },
145:        )
146:        .await;
147:        match answered {
148:            Ok(removed) => entries_removed += removed,
149:            // The daemon refused the request whole (a read-only module,
150:            // another build, no answer): none of these operands went.
151:            Err(RmError::Refused(error)) => {
152:                for &at in &group {
153:                    said.failed(Failed {
154:                        operand: at,
155:                        path: operands[at].typed().to_vec(),
156:                        reason: format!("{error:#}"),
157:                        refused: false,
158:                    });
159:                }
160:            }
161:            // The answer stopped part way: what was reported stands, and
162:            // what else went is not known.
163:            Err(error @ RmError::Interrupted(_)) => {
164:                unfinished.push(format!("{}: {error}", first.remote.host_port_display()));
165:            }
166:        }
167:    }
168:    said.finish();
169:
170:    if args.json {
171:        println!(
172:            "{}",
173:            serde_json::to_string_pretty(&serde_json::json!({
174:                "entries_removed": entries_removed,
175:                "failures": said.listed,
176:                "unfinished": unfinished,
177:            }))?
178:        );
179:    } else {
180:        for line in &unfinished {
181:            eprintln!("blit rm: {line}");
182:        }
183:    }
184:    Ok(if said.any || !unfinished.is_empty() {
185:        ExitCode::from(1)
186:    } else {
187:        ExitCode::SUCCESS
188:    })
189:}
