191:/// What `rm` says of the entries it did not remove: printed as each is
192:/// learned, or collected for `--json`.
193:struct Said {
194:    json: bool,
195:    listed: Vec<serde_json::Value>,
196:    /// The operands `rm` itself refuses, waiting for their turn: each is
197:    /// said before anything about an operand typed after it.
198:    refused: std::collections::VecDeque<Failed>,
199:    any: bool,
200:}
201:
202:impl Said {
203:    fn failed(&mut self, failed: Failed) {
204:        while self
205:            .refused
206:            .front()
207:            .is_some_and(|before| before.operand < failed.operand)
208:        {
209:            let before = self.refused.pop_front().expect("one is waiting");
210:            self.say(before);
211:        }
212:        self.say(failed);
213:    }
214:
215:    /// The command is over: whatever still waits is said.
216:    fn finish(&mut self) {
217:        while let Some(waiting) = self.refused.pop_front() {
218:            self.say(waiting);
219:        }
220:    }
221:
222:    /// A name is written as `rm` writes it (cr-uv2-5): quoted so that
223:    /// it reads back as the name it is — `'bad'$'\377''.dat'`. Shown as
224:    /// text, a name that is not text was told of in the words for
225:    /// another file, the one holding U+FFFD where this holds a byte.
226:    fn say(&mut self, failed: Failed) {
227:        self.any = true;
228:        if self.json {
229:            self.listed.push(serde_json::json!({
230:                "path": String::from_utf8_lossy(&failed.path),
231:                "reason": failed.reason,
232:            }));
233:            return;
234:        }
235:        let name = quote::for_shell(&failed.path, true);
236:        if failed.refused {
237:            eprintln!("blit rm: {}: skipping {name}", failed.reason);
238:        } else {
239:            eprintln!("blit rm: cannot remove {name}: {}", failed.reason);
240:        }
241:    }
242:}
