244:/// What is asked before anything is removed: the operands, as typed.
245:fn question<'a>(operands: impl ExactSizeIterator<Item = &'a Operand>) -> String {
246:    const NAMED: usize = 3;
247:    let more = operands.len().saturating_sub(NAMED);
248:    let mut named: Vec<String> = operands
249:        .take(NAMED)
250:        .map(|operand| quote::for_shell(operand.typed(), true))
251:        .collect();
252:    if more > 0 {
253:        named.push(format!("{more} more"));
254:    }
255:    let list = match named.len() {
256:        1 => named.remove(0),
257:        _ => {
258:            let last = named.pop().expect("more than one");
259:            format!("{} and {last}", named.join(", "))
260:        }
261:    };
262:    format!("Remove {list}?")
263:}
